insert into reviewer_private.curated_skills(id,kit)
select item->>'id', item from jsonb_array_elements($kits$[{"id":"verbal-evidence","title":"Supporting details","lesson":"Start with the claim. A supporting detail supplies a fact, example or observation that makes that claim more convincing.","example":"For “The hallway is quieter after the repair,” sound readings before and after the repair are relevant. The color of the new panels is not.","rows":[["Which detail supports “The hose leaks”?","Water drips from the hose while it is on.","The hose is green.",0,"Drips show that water escapes. Color does not indicate a leak."],["Which detail supports “The new route is shorter”?","The route measures 8 km instead of 12 km.","The van is newer.",0,"Distance measures route length. The vehicle could change without changing the route length."],["A notice claims the redesign improved readability. Which fact best supports it?","The notice uses a new font.","Readers found the instructions correctly more often.",1,"Reader success directly measures readability. Using a new font describes the change without measuring its effect."],["Which detail supports “More residents used the clinic in May”?","The clinic opened in 2014.","May’s register lists 430 visits, compared with 310 in April.",1,"The visit comparison supports increased use. The opening year does not measure recent use."],["A writer claims “Some containers lose heat rapidly.” Which observation supports the limited claim?","One container has a chipped handle.","Two of ten containers cooled sharply under the same conditions.",1,"Two rapid declines are enough to support “some.” A chipped handle alone gives no cooling measurement."],["The report says “Adding a second checkout cut the median wait.” Which detail supports that specific outcome?","Shoppers preferred one cashier’s greeting.","The middle wait fell from six minutes to three after the second checkout opened.",1,"The middle wait is the median. The reported drop measures the claimed change."]]},{"id":"verbal-context","title":"English context clues","lesson":"Look for a definition, example, contrast or consequence near an unfamiliar word. Choose the meaning that makes the surrounding details fit.","example":"“The trail was arid, with little rain and no streams.” The rain and stream clues suggest that arid means very dry.","rows":[["“The room was frigid. Everyone kept their coats on.” What does frigid mean?","Very crowded","Very cold",1,"Keeping coats on suggests cold. The sentence gives no clue about crowd size."],["“The label was legible, so Rina read it without trouble.” What does legible mean?","Easy to read","Easy to peel",0,"The consequence is successful reading. Peeling is unrelated."],["“Unlike his gregarious brother, Noel preferred working alone.” What does gregarious suggest?","Forgetful","Sociable",1,"The contrast is with working alone, so the brother enjoys company. Memory is irrelevant."],["“We rationed the water, giving each family only two bottles.” What does rationed mean?","Warmed the supply","Limited each share",1,"The specific allotment explains rationing. No heating is described."],["“The witness’s account was inconsistent: she placed the event at noon and later said it was after dusk.” Which clue explains inconsistent?","The event involved a witness.","The two times conflict.",1,"Mutually conflicting times make the account inconsistent. Having a witness does not explain the word."],["“The fabric was permeable. Rain passed through it.” Which replacement preserves the meaning?","Unusually thin","Able to let liquid through",1,"The second sentence states what passes through. Thinness can occur without permeability."]]},{"id":"verbal-tenses","title":"Verb tense and time","lesson":"Find the time clue and decide whether the action is finished, habitual or later. Match the verb to that time relationship.","example":"In “Yesterday, Ada checked the files,” yesterday and checked both place the action in the past.","rows":[["“Yesterday, Lea ___ the forms.” Choose the verb.","filed","files",0,"Yesterday is a finished past time, so filed is appropriate. Files ordinarily describes a habit or present action."],["The schedule still applies today. “Every Monday, the office ___ at eight.” Choose the verb.","opened","opens",1,"Every Monday describes a current routine in this sentence, so opens is suitable. Opened would need a past frame."],["Which verb phrase suits “By next Friday, the team ___ the inventory”?","will have completed","had completed",0,"Next Friday is a future deadline. Will have completed places completion before that future point. Had completed takes a past reference point."],["“When the lights went out, Ana ___ a report.” Which phrase describes an action already in progress?","will write","was writing",1,"Was writing depicts an ongoing past action when the event happened. Will write places it in the future."],["Which version keeps both actions in a completed past sequence?","Lia checked the totals and filed the report.","Lia checks the totals and filed the report.",0,"Both checked and filed locate their actions in the past. Checks changes the time without a reason."],["“Before the bus arrived, we ___ our bags.” Which phrase explicitly marks packing as earlier than the past arrival?","had packed","will have packed",0,"Had packed marks completed action before another past event. Will have packed takes a future reference point."]]},{"id":"analytical-analogy","title":"Analogies and ordered relationships","lesson":"State the relationship between the first two terms in a short phrase. Apply that same relationship in the same direction to the second pair.","example":"Thermometer is to temperature as ruler is to length. Each first item measures its second item.","rows":[["Pencil is to writing as scissors are to …","paper","cutting",1,"Writing is what a pencil does. Cutting is what scissors do. Paper is a material they can cut."],["Nest is to bird as kennel is to …","dog","roof",0,"Each first term is a shelter for the second. A roof is a part of a shelter."],["Page is to book as tile is to …","floor","grout",0,"A page can be one composing part of a book. A tile can be one composing part of a floor. Grout fills joints."],["Chapter is to book as minute is to …","second","hour",1,"The first term is a segment of the second. A second is smaller than a minute, which reverses the direction."],["Apprentice is to mentor as student is to …","teacher","classroom",0,"The second person guides the first. A classroom is a setting, rather than a guide."],["Which pair matches “lock is to key,” with the second item used to operate the first?","Key is to lock","Screw is to screwdriver",1,"A screwdriver operates a screw. Key is to lock reverses the tool direction."]]},{"id":"analytical-classification","title":"Classification by a rule","lesson":"Write the membership condition as a test. Apply the same test to every candidate and check each part of a combined rule.","example":"A rule says “even and greater than five.” Six qualifies because it satisfies both conditions. Four is even, but is too small.","rows":[["Group by numbers divisible by 3. Which belongs?","14","12",1,"Twelve is 3 × 4. Fourteen leaves a remainder when divided by three."],["A file belongs only if signed and dated. Which file belongs?","Signed, dated","Signed, undated",0,"“And” requires both conditions. A signature alone is insufficient."],["Which pair fits the rule “same first letter, different last letter”?","cat, cup","cat, bat",0,"Cat and cup begin with c and end differently. Cat and bat end together and start differently."],["A record qualifies if archived or starred, including both. Which record fails?","Neither archived nor starred","Archived and starred",0,"Inclusive “or” accepts either or both. Neither satisfies the rule."],["Which number is even but not divisible by four?","14","16",0,"Fourteen divides by two and leaves a remainder of two when divided by four. Sixteen divides evenly by four."],["Rule: allow exactly one of two permissions. Which user is allowed?","One with read only","One with both",0,"Exactly one permits one permission. Both gives two, which exceeds the rule."]]},{"id":"analytical-evidence","title":"Evidence and conclusions","lesson":"Separate an observation from its interpretation. Strong evidence addresses the specific claim and, where possible, rules out plausible alternative explanations.","example":"If a plant grows faster after more light, check whether water and soil also changed before attributing the result to light.","rows":[["Which is direct evidence that a door is unlocked?","The handle opens it without a key.","The door has fresh paint.",0,"Opening without a key directly checks the lock state. Paint gives no lock information."],["A sample contained 8 cracked tiles out of 100. Which claim is directly supported?","Eight sampled tiles were cracked.","Every delivery contains cracked tiles.",0,"The count describes the observed sample. It does not establish a universal delivery pattern."],["What would best test whether extra light increases growth?","Compare two plants of different species with different water.","Compare similar plants with the same care and different light.",1,"Holding other conditions steady makes light the clearer explanation. Multiple changes obscure the cause."],["Scores rose after a new lesson and an easier test. What weakens the causal claim?","The easier test could account for the rise.","Students used pencils.",0,"Difficulty changed at the same time, so the lesson’s effect is unclear. Pencil use is unconnected."],["Which evidence best supports a claim about average wait across the full week?","A single observation on Friday","Measurements across all opening days and times",1,"Broad coverage reduces the risk that one unusual period dominates the estimate. A single observation cannot represent the whole week well."],["Every surveyed customer liked the service. All surveys came from the loyalty club. What limits the conclusion?","Customers outside the club may be underrepresented.","The result can be expressed as a percentage.",0,"The sample omits other customers. Expressing the result as a percentage does not solve that coverage problem."]]},{"id":"filipino-reading","title":"Pag-unawa sa binasa","lesson":"Tukuyin kung ang tanong ay humihingi ng tuwirang detalye, dahilan o mahihinuha. Itapat ang sagot sa binasa.","example":"“Isinara ang bintana dahil lumakas ang ulan.” Ang dahilan ay paglakas ng ulan. Ang kilos ay pagsasara ng bintana.","rows":[["“Nagdala ng payong si Nena dahil makulimlim.” Ano ang dinala niya?","Sombrero","Payong",1,"Tuwirang binanggit ang payong. Walang binanggit na sombrero."],["“Pumasok si Lino sa silid upang magbasa.” Bakit siya pumasok?","Upang kumain","Upang magbasa",1,"Ipinakikilala ng upang ang layunin. Ang layunin dito ay magbasa."],["“Inuna ni Mara ang pagwawalis bago ang pagdidilig.” Ano ang unang ginawa?","Nagwalis","Nagdilig",0,"Ipinahihiwatig ng inuna at bago ang pagkakasunod-sunod. Nauna ang pagwawalis."],["“Walang laman ang bote. Dinala ito ni Ivo sa gripo.” Ano ang makatuwirang hinuha?","Malamang na pupunuin niya ang bote.","Itatapon niya agad ang bote.",0,"Walang laman ang bote at may tubig sa gripo. Magkaugnay ang mga detalyeng sumusuporta sa pagpuno."],["“Kapos ang suplay kaya naghati-hati ang mga pamilya.” Ano ang sanhi ng paghahati-hati?","Pagdami ng pagkain","Kakulangan ng suplay",1,"Ang unang sugnay ang sanhi. Ang kaya ang nag-uugnay nito sa naging bunga."],["“Nais sanang lumabas ni Cora. Nang kumulog, nanatili siya sa loob.” Alin ang pinakamalapit na buod?","Nagbago ang balak niya nang kumulog.","Lumabas siya kahit kumulog.",0,"Ang unang pangungusap ang balak. Ang ikalawa ang nangyari matapos kumulog."]]},{"id":"clerical-secondary","title":"Secondary filing keys","lesson":"A secondary key breaks ties in the primary key. Apply keys in the stated order, even when a later key would give a different result.","example":"Under surname then given name, Cruz, Ana precedes Cruz, Bea. The surname ties, so the given name decides.","rows":[["Sort by surname then given name. Which comes first?","Cruz, Bea","Cruz, Ana",1,"The surnames tie. A precedes B in the given names."],["Sort by ascending ID then surname. Which comes first?","8 — Santos","12 — Abad",0,"The IDs differ, so the smaller ID comes first. Surname order is considered only for a tie."],["Sort by department then ascending ID. Which comes first?","Records — 2","Accounts — 12",1,"Accounts precedes Records. The number cannot override the department order."],["Sort by surname, given name, then number. Cruz, Ana — 7 ties Cruz, Ana — 5 on which keys?","Surname and given name","Number only",0,"Both name fields match. The different record numbers decide the order."],["Sort by date ascending, then name. Both records are dated 5 May. Which comes first?","Abad","Santos",0,"The dates tie. A comes before S when comparing the names."],["Sort by office, then descending ID. Where does HR — 110 go relative to HR — 17?","Before HR — 17","After HR — 17",0,"The office ties. Descending puts the larger number 110 before 17."]]}]$kits$::jsonb) item
on conflict (id) do nothing;
